namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Description = "Start your day right with these morning favorites", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday meals", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Light bites for any time of day", Icon = "🍿" },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt\nButter for cooking",
                Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a buttered pan over medium heat.\n5. Pour 1/4 cup batter per pancake.\n6. Flip when bubbles form on surface.\n7. Cook until golden brown.",
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan cheese\nCaesar dressing\nGrilled chicken (optional)",
                Steps = "1. Wash and chop romaine lettuce.\n2. Toss with Caesar dressing.\n3. Top with croutons and shaved parmesan.\n4. Add grilled chicken if desired.\n5. Serve immediately.",
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Ingredients = "400g spaghetti\n500g ground beef\n1 onion, diced\n3 cloves garlic\n400g crushed tomatoes\n2 tbsp tomato paste\nOlive oil\nSalt and pepper\nFresh basil",
                Steps = "1. Cook spaghetti according to package directions.\n2. Sauté onion and garlic in olive oil.\n3. Add ground beef and brown.\n4. Stir in crushed tomatoes and tomato paste.\n5. Simmer for 20 minutes.\n6. Season with salt and pepper.\n7. Serve sauce over spaghetti with fresh basil.",
                AverageRating = 4.8, RatingCount = 25
            },
            new()
            {
                Id = 4, Title = "Chocolate Brownies", Category = "Desserts",
                Ingredients = "200g dark chocolate\n150g butter\n3 eggs\n1 cup sugar\n3/4 cup flour\n1 tsp vanilla extract\nPinch of salt",
                Steps = "1. Preheat oven to 350°F (175°C).\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until fluffy.\n4. Fold in chocolate mixture.\n5. Add flour, vanilla, and salt.\n6. Pour into greased 9x9 pan.\n7. Bake 25-30 minutes.\n8. Cool before cutting.",
                AverageRating = 4.9, RatingCount = 30
            },
            new()
            {
                Id = 5, Title = "Trail Mix Energy Bites", Category = "Snacks",
                Ingredients = "1 cup oats\n1/2 cup peanut butter\n1/3 cup honey\n1/2 cup chocolate chips\n1/4 cup dried cranberries\n1/4 cup sunflower seeds",
                Steps = "1. Mix all ingredients in a large bowl.\n2. Refrigerate for 30 minutes.\n3. Roll into 1-inch balls.\n4. Store in refrigerator for up to a week.",
                AverageRating = 4.3, RatingCount = 15
            },
            new()
            {
                Id = 6, Title = "Avocado Toast", Category = "Breakfast",
                Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice\nOptional: poached egg",
                Steps = "1. Toast bread until golden.\n2. Mash avocado with lemon juice, salt, and pepper.\n3. Spread avocado on toast.\n4. Sprinkle with red pepper flakes.\n5. Top with a poached egg if desired.",
                AverageRating = 4.1, RatingCount = 18
            },
        ];
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAllRecipes() => _recipes;

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int rating)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            var totalRating = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalRating + rating) / recipe.RatingCount;
        }
    }
}

