@page "/recipes/{CategoryName}"
@using RecipeHub.Services

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@category?.Icon @CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <div class="recipe-meta">
                    <span class="rating">⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                </div>
            </a>
        }
    </div>
}

<a href="/" class="back-link">← Back to Categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeHub.Models.Recipe> recipes = [];
    private RecipeHub.Models.RecipeCategory? category;

    protected override void OnParametersSet()
    {
        var categories = RecipeService.GetCategories();
        category = categories.FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services

@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <h1>Recipe not found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <PageTitle>@recipe.Title - RecipeHub</PageTitle>

    <a href="/recipes/@recipe.Category.ToLower()" class="back-link">← Back to @recipe.Category</a>

    <article class="recipe-detail">
        <h1>@recipe.Title</h1>
        <span class="category-badge">@recipe.Category</span>

        <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />

        <section class="recipe-section">
            <h2>🧾 Ingredients</h2>
            <ul class="ingredients-list">
                @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>📝 Steps</h2>
            <ol class="steps-list">
                @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    var text = step.TrimStart();
                    if (text.Length > 2 && text[1] == '.')
                        text = text[3..];
                    <li>@text</li>
                }
            </ol>
        </section>
    </article>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services

@inject RecipeService RecipeService

<div class="star-rating-widget">
    <div class="current-rating">
        <span>⭐ @CurrentRating.ToString("F1")</span>
        <span class="rating-count">(@RatingCount ratings)</span>
    </div>
    <div class="rate-section">
        <span class="rate-label">Rate this recipe:</span>
        <div class="stars">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <button class="star-btn @(star <= hoveredStar ? "hovered" : "") @(star <= selectedStar ? "selected" : "")"
                        @onmouseover="() => hoveredStar = star"
                        @onmouseout="() => hoveredStar = 0"
                        @onclick="() => Rate(star)"
                        aria-label="Rate @star stars">
                    @(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "★" : "☆")
                </button>
            }
        </div>
        @if (submitted)
        {
            <span class="rating-feedback">Thanks for rating!</span>
        }
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoveredStar;
    private int selectedStar;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedStar = stars;
        RecipeService.RateRecipe(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services

@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="success-message">
        <h2>✅ Recipe Submitted!</h2>
        <p>Thank you for sharing "<strong>@model.Title</strong>" with the community.</p>
        <a href="/recipe/@submittedId">View your recipe</a>
        <span> | </span>
        <button class="btn-link" @onclick="Reset">Submit another</button>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" class="recipe-form">
        <DataAnnotationsValidator />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => model.Title" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.Category" />
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="model.Ingredients" rows="6"
                           placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => model.Ingredients" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="model.Steps" rows="6"
                           placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <ValidationMessage For="() => model.Steps" />
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel model = new();
    private bool submitted;
    private int submittedId;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps,
        };
        RecipeService.AddRecipe(recipe);
        submittedId = recipe.Id;
        submitted = true;
    }

    private void Reset()
    {
        model = new();
        submitted = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

