toolArgs.file_text:
@page "/recipe/{Id:int}"
@using RecipeHub.Services

@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <h1>Recipe not found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <PageTitle>@recipe.Title - RecipeHub</PageTitle>

    <a href="/recipes/@recipe.Category.ToLower()" class="back-link">← Back to @recipe.Category</a>

    <article class="recipe-detail">
        <h1>@recipe.Title</h1>
        <span class="category-badge">@recipe.Category</span>

        <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />

        <section class="recipe-section">
            <h2>🧾 Ingredients</h2>
            <ul class="ingredients-list">
                @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>📝 Steps</h2>
            <ol class="steps-list">
                @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    var text = step.TrimStart();
                    if (text.Length > 2 && text[1] == '.')
                        text = text[3..];
                    <li>@text</li>
                }
            </ol>
        </section>
    </article>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services

@inject RecipeService RecipeService

<div class="star-rating-widget">
    <div class="current-rating">
        <span>⭐ @CurrentRating.ToString("F1")</span>
        <span class="rating-count">(@RatingCount ratings)</span>
    </div>
    <div class="rate-section">
        <span class="rate-label">Rate this recipe:</span>
        <div class="stars">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <button class="star-btn @(star <= hoveredStar ? "hovered" : "") @(star <= selectedStar ? "selected" : "")"
                        @onmouseover="() => hoveredStar = star"
                        @onmouseout="() => hoveredStar = 0"
                        @onclick="() => Rate(star)"
                        aria-label="Rate @star stars">
                    @(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "★" : "☆")
                </button>
            }
        </div>
        @if (submitted)
        {
            <span class="rating-feedback">Thanks for rating!</span>
        }
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoveredStar;
    private int selectedStar;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedStar = stars;
        RecipeService.RateRecipe(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

